#!/usr/bin/env bash
# =============================================================================
# security_audit.sh - read-only security report for RHEL-family and
# Debian/Ubuntu-family servers.
#
# Generated by: Claude (Anthropic). Review, test, and cite before submitting.
#
# What it checks:
#   1. Failed SSH logins in the last 24 hours (from the systemd journal)
#   2. Accounts with UID 0 (root privileges)
#   3. Accounts with empty password fields
#   4. Listening TCP/UDP ports (via ss)
#
# Output: timestamped report in $REPORT_DIR (not /tmp)
# Exit codes: 0 = no problems, 1 = problem(s) found, 2 = script could not run
# Must run as root (needs /etc/shadow and the full journal).
# Installs nothing and changes no system settings; it only creates its own
# report directory and report files.
#
# Example root crontab entry (crontab -e as root), runs daily at 02:15:
#   15 2 * * * /usr/local/sbin/security_audit.sh
# =============================================================================

# Cron runs with a minimal PATH, so set one explicitly.
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
export PATH

# ---- Settings ---------------------------------------------------------------
REPORT_DIR="/var/log/security-audit"   # where reports are saved
FAILED_SSH_THRESHOLD=0                 # more failures than this = problem

# ---- Pre-flight checks ------------------------------------------------------
# id -u prints the numeric user ID; root is 0.
if [ "$(id -u)" -ne 0 ]; then
    echo "ERROR: run this script as root (e.g. sudo $0)" >&2
    exit 2
fi

# Create the report directory if missing; restrict it to root.
if ! mkdir -p "$REPORT_DIR"; then
    echo "ERROR: cannot create $REPORT_DIR" >&2
    exit 2
fi
chmod 700 "$REPORT_DIR"

HOST="$(hostname -s)"                          # short hostname
STAMP="$(date +%Y-%m-%d_%H-%M-%S)"             # timestamp for filename
REPORT="$REPORT_DIR/audit_${HOST}_${STAMP}.txt"
PROBLEMS=0                                     # count of problem categories

# ---- Build the report -------------------------------------------------------
# Everything inside { } is written to the report file. A { } group runs in the
# current shell, so changes to PROBLEMS are kept afterward.
{
    echo "Security audit report"
    echo "Host:      $(hostname -f 2>/dev/null || hostname)"
    echo "Generated: $(date)"
    echo "OS:        $(. /etc/os-release 2>/dev/null && echo "$PRETTY_NAME")"
    echo

    # ---- 1. Failed SSH logins, last 24 hours --------------------------------
    echo "=== 1. Failed SSH logins (last 24 hours) ==="
    if command -v journalctl >/dev/null 2>&1; then
        # -t filters by syslog identifier. Older OpenSSH logs as "sshd";
        # OpenSSH 9.8+ logs per-connection messages as "sshd-session".
        # This works whether the service unit is named sshd (RHEL) or ssh (Ubuntu).
        FAILED_LINES="$(journalctl --since "24 hours ago" --no-pager -q \
            -t sshd -t sshd-session 2>/dev/null \
            | grep -E "Failed password|Failed publickey|Invalid user")"
        if [ -n "$FAILED_LINES" ]; then
            FAILED_COUNT="$(printf '%s\n' "$FAILED_LINES" | wc -l)"
        else
            FAILED_COUNT=0
        fi
        echo "Failed attempts: $FAILED_COUNT"
        [ "$FAILED_COUNT" -gt 0 ] && printf '%s\n' "$FAILED_LINES"
        if [ "$FAILED_COUNT" -gt "$FAILED_SSH_THRESHOLD" ]; then
            echo "PROBLEM: failed SSH logins above threshold ($FAILED_SSH_THRESHOLD)"
            PROBLEMS=$((PROBLEMS + 1))
        fi
    else
        echo "PROBLEM: journalctl not found; cannot check SSH logins"
        PROBLEMS=$((PROBLEMS + 1))
    fi
    echo

    # ---- 2. Accounts with UID 0 ---------------------------------------------
    echo "=== 2. Accounts with UID 0 (root privileges) ==="
    # /etc/passwd fields are colon-separated; field 3 is the UID.
    awk -F: '$3 == 0 { print $1 }' /etc/passwd
    EXTRA_ROOT="$(awk -F: '$3 == 0 && $1 != "root" { print $1 }' /etc/passwd)"
    if [ -n "$EXTRA_ROOT" ]; then
        echo "PROBLEM: non-root account(s) with UID 0: $EXTRA_ROOT"
        PROBLEMS=$((PROBLEMS + 1))
    fi
    echo

    # ---- 3. Accounts with empty passwords -----------------------------------
    echo "=== 3. Accounts with empty passwords ==="
    # /etc/shadow field 2 is the password hash; empty means no password needed.
    EMPTY_PW="$(awk -F: '$2 == "" { print $1 }' /etc/shadow)"
    if [ -n "$EMPTY_PW" ]; then
        echo "$EMPTY_PW"
        echo "PROBLEM: account(s) with empty passwords found"
        PROBLEMS=$((PROBLEMS + 1))
    else
        echo "None found"
    fi
    echo

    # ---- 4. Listening ports -------------------------------------------------
    echo "=== 4. Listening ports (ss -tulpn) ==="
    # -t TCP, -u UDP, -l listening only, -p owning process, -n numeric ports
    ss -tulpn
    echo

    echo "=== Summary ==="
    echo "Problem categories found: $PROBLEMS"
} > "$REPORT" 2>&1

chmod 600 "$REPORT"   # report contains account names; root-only

# Print a one-line result to stdout (cron mails this to root if mail is set up).
echo "Report saved to $REPORT ($PROBLEMS problem categories)"

# Non-zero exit if anything was flagged.
if [ "$PROBLEMS" -gt 0 ]; then
    exit 1
fi
exit 0
